def creer_files_par_defaut(apps, schema_editor):
    """Crée la file par défaut des services existants."""
    Service = apps.get_model("centres", "Service")
    FileAttente = apps.get_model("centres", "FileAttente")

    for service in Service.objects.all():
        if not FileAttente.objects.filter(service=service, par_defaut=True).exists():
            FileAttente.objects.create(
                centre_id=service.centre_id,
                service=service,
                code=service.code,
                nom=service.nom,
                par_defaut=True,
            )


TRIGGER_FILE_CENTRE = """
CREATE OR REPLACE FUNCTION centres_verifier_centre_service()
RETURNS trigger AS $$
BEGIN
    IF NEW.centre_id IS DISTINCT FROM (
        SELECT centre_id FROM centres_service WHERE id = NEW.service_id
    ) THEN
        RAISE EXCEPTION 'Incohérence de centre : % (service %) n''appartient pas au centre %',
            TG_TABLE_NAME, NEW.service_id, NEW.centre_id;
    END IF;
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER fileattente_coherence_centre
BEFORE INSERT OR UPDATE OF centre_id, service_id ON centres_fileattente
FOR EACH ROW EXECUTE FUNCTION centres_verifier_centre_service();
"""

